(()=>{'use strict';
const root=document.getElementById('app');
const data=window.ASK_GS_DATA;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function validate(d){
 if(!d?.release||!Array.isArray(d.content?.verses)||!d.content.verses.length||!Array.isArray(d.content.tokens))throw Error('Pakej kandungan tidak lengkap.');
 const ids=new Set();for(const v of d.content.verses){if(!v.id||ids.has(v.id)||typeof v.arabic_candidate!=='string'||typeof v.translation_candidate_ms!=='string')throw Error('Unit kandungan tidak sah.');ids.add(v.id);}
 if(d.content.tokens.some(t=>!ids.has(t.ayat_id)))throw Error('Pemetaan kalimah tidak sah.');
 for(const a of ['adult','kid','founder'])if(!d.assets?.[a]?.path)throw Error('Manifest visual tidak lengkap.');
}
try{validate(data)}catch(e){root.innerHTML=`<section class="failure"><h1>Pratonton belum dapat dibuka</h1><p>${esc(e.message)}</p><p>Muat semula halaman atau gunakan pakej lengkap.</p></section>`;return;}
const {release:r,content:c,assets}=data;
const profiles=['adult','kid'];const routes=['opening','intro','journey','learn','words','readingEnd','practice','flash','fullReading','sources','records','sequence','sequenceMenu','reverse','reflect','stage'];
const prefix=`ASK-QH-GS:${r.schemaVersion}:${r.appId}:`;
let stageKey='learn';let storageOK=true,notice='',profile='adult',route='opening',timer=null,ticker=null,generation=0;
let records={adult:{selectedUnit:null},kid:{selectedUnit:null}};let activeUnit=c.verses[0].id,activeToken=0;let learning;let audio;let journeyTools;let trainingType="MCQ";let retryScope='training';let textSize='normal',zoomTarget=null,zoomScale=100,zoomReturnScroll=0,resetPending=null;let pairLeft=null;let flashId=c.items.find(i=>i.type==='FLASH').id;
function learningStorage(){try{return localStorage}catch{return null}}
function read(key){try{return localStorage.getItem(key)}catch{storageOK=false;return null}}
function write(key,value){try{localStorage.setItem(key,value);return true}catch{storageOK=false;return false}}
for(const p of profiles){const raw=read(prefix+p);if(!raw)continue;try{const d=JSON.parse(raw);if(d.appId===r.appId&&d.profileId===p&&d.schemaVersion===r.schemaVersion&&d.contentHash===r.contentHash&&c.verses.some(v=>v.id===d.selectedUnit))records[p].selectedUnit=d.selectedUnit;else if(d.selectedUnit!==null)notice='Rekod pratonton versi lain dikekalkan dan tidak digunakan.';}catch{notice='Rekod pratonton lama tidak dapat dibaca. Anda masih boleh meneruskan.';}}
textSize=read(prefix+'textSize')==='large'?'large':'normal';const preferred=read(prefix+'preference');if(profiles.includes(preferred))profile=preferred;
const pathname=location.pathname;const forced=pathname.startsWith('/kanak-kanak')?'kid':pathname.startsWith('/dewasa')?'adult':null;if(forced)profile=forced;
try{audio=new window.ASKDeviceAudio({content:c,onStatus:updateAudioUI});audio.bindLifecycle(document,window);learning=new window.ASKStudyEngine({content:c,release:r,storage:learningStorage(),profile,audio});journeyTools=new window.ASKJourneyTools({content:c,release:r,storage:learningStorage(),profile})}catch(e){root.innerHTML='<section class="failure"><h1>Pembelajaran belum dapat dibuka</h1><p>Pakej enjin atau kandungan tidak sepadan. Gunakan salinan lengkap binaan ini.</p></section>';return}

function save(){write(prefix+profile,JSON.stringify({schemaVersion:r.schemaVersion,appId:r.appId,profileId:profile,contentHash:r.contentHash,selectedUnit:records[profile].selectedUnit}));write(prefix+'preference',profile);}
function clearTimers(){generation++;clearTimeout(timer);clearInterval(ticker);timer=null;ticker=null;}
function routeFromHash(){
 const raw=location.hash.slice(1);if(!raw)return 'opening';let parts;try{parts=raw.split('/').map(decodeURIComponent)}catch{return 'journey'}
 if(!routes.includes(parts[0]))return 'journey';if(parts[0]==='stage'){if(!window.ASKUnifiedJourney.steps.some(s=>s.id===parts[1]))return 'journey';stageKey=parts[1];}if(parts[0]==='flash'){const id=parts[1]||learning.currentFlash()?.item.id||learning.flashCards()[0].id;if(!learning.flashCards().some(i=>i.id===id)){notice='Kad tidak ditemui. Pilih Kad Imbas daripada perjalanan.';return 'journey'}flashId=id;}if(parts[0]==='practice'){retryScope=['training','full','retention'].includes(parts[2])?parts[2]:'training';trainingType=['TF','PAIR','ORDER','FULL','RETENTION','RETRY'].includes(parts[1])?parts[1]:'MCQ';}
 if(['learn','words'].includes(parts[0])){const current=learning.getCurrentStudy(),id=parts[1]||current?.ayatId||c.verses[0].id;if(!c.verses.some(v=>v.id===id)){notice='Ayat tidak ditemui. Pilih ayat daripada peta.';return 'journey'}activeUnit=id;const ts=c.tokens.filter(t=>t.ayat_id===id);const n=parts[2]===undefined?(current?.ayatId===id?current.tokenIndex:0):Number(parts[2]);activeToken=Number.isInteger(n)&&n>=0&&n<ts.length?n:0;}
 return parts[0];
}
function go(next){if(!routes.includes(next.split('/')[0]))return;resetPending=null;zoomTarget=null;learning.stopAudio('navigation');if(['sequence','reverse'].includes(route)&&next!==route)journeyTools.pause(route);if(route==='practice'&&next.split('/')[0]!=='practice')learning.pauseTraining();clearTimers();if(location.hash==='#'+next){route=routeFromHash();render();return}location.hash=next;}
function footer(){return `<footer>${esc(r.buildId)} · Perjalanan belajar · ${esc(profile==='kid'?'Kanak-kanak':'Dewasa')}<br>Calon standard; belum keluaran GOLDEN.</footer>`}
function switcher(){return `<div class="profile-switch" role="group" aria-label="Pilih profil">${profiles.map(p=>`<button data-action="profile" data-value="${p}" aria-pressed="${profile===p}">${p==='kid'?'Kanak-kanak':'Dewasa'}</button>`).join('')}</div>`}
function header(){return `<header class="top"><div class="brand">FATIHAH<small>Surah Al-Fatihah · ${profile==='kid'?'Kanak-kanak':'Dewasa'}</small></div><div class="header-actions"><button data-action="textSize" aria-pressed="${textSize==='large'}">${textSize==='large'?'Saiz teks biasa':'Besarkan teks'}</button><button data-action="go" data-value="journey">Perjalanan</button><button data-action="go" data-value="intro">Pengenalan</button></div></header>`}
function button(label,value,style=''){return `<button class="btn ${style}" data-action="go" data-value="${value}">${label}</button>`}
function storageNotice(){return `${notice?`<p class="notice" role="status">${esc(notice)}</p>`:''}${!storageOK?'<p class="notice" role="status">Pilihan tidak dapat disimpan. Anda masih boleh meneruskan pada pelayar ini.</p>':''}`}
function startTimer(token){if(route!=='opening'||document.hidden||timer||token!==generation)return;const began=Date.now();ticker=setInterval(()=>{const count=document.getElementById('count');if(count)count.textContent=Math.max(0,Math.ceil(3-(Date.now()-began)/1000));},100);timer=setTimeout(()=>{if(route==='opening'&&token===generation)go('intro')},3000);}
function opening(){root.className='';root.innerHTML=`<section class="splash ${profile==='kid'?'kid':''}" aria-label="Pembukaan FATIHAH"><img id="opening-image" src="${esc(assets[profile].path)}" alt="${profile==='kid'?'Kanak-kanak':'Dewasa'} membaca Al-Fatihah dalam solat; visual asal yang diluluskan"><span class="build-tag">RC02 · CALON TERPADU</span><div class="splash-title"><span class="eyebrow">${profile==='kid'?'KANAK-KANAK':'DEWASA'} · SURAH AL-FATIHAH</span><h1>FATIHAH</h1><h2>Memahami &amp; Menghayati<br>Surah Al-Fatihah</h2><p>Baca · Faham · Hayati · Amalkan</p></div><div class="splash-controls">${switcher()}${button('Teruskan →','intro','gold')}<p id="count-message">Ke pengenalan dalam <span id="count">3</span> saat selepas gambar tersedia.</p></div></section>`;
 const im=document.getElementById('opening-image'),token=generation;
 const ready=async()=>{try{await im.decode?.()}catch{}if(!im.isConnected||token!==generation)return;startTimer(token)};
 im.addEventListener('load',ready,{once:true});im.addEventListener('error',()=>{if(token!==generation)return;im.hidden=true;root.querySelector('.splash').classList.add('splash-fallback');document.getElementById('count-message').textContent='Gambar belum tersedia. Tekan Teruskan untuk masuk.';},{once:true});
 if(im.complete&&im.naturalWidth)ready();
}
function intro(){return `${switcher()}<figure class="founder"><img src="${esc(assets.founder.path)}" alt="Identiti pengasas ACG · Ahmad Takiuddin Shuaib"><figcaption>Aset identiti pengasas asal · diwarisi daripada baseline diluluskan</figcaption><button class="btn outline" data-action="zoomImage" data-value="founder">Besarkan imej pengasas</button></figure><section class="hero"><span class="eyebrow">KENALI FATIHAH</span><h1>Memahami &amp; menghayati<br>Al-Fatihah.</h1><p>${c.verses.length} ayat. Satu perjalanan memahami makna, sedikit demi sedikit.</p></section><section class="card"><h2>${profile==='kid'?'Jom belajar bersama':'Belajar mengikut kemampuan'}</h2><p>Kenali kalimah, fahami ayat dan lihat perjalanan pembelajaran anda.</p><p class="muted">${profile==='kid'?'Belajar bersama ibu bapa atau guru.':'Pilih langkah mengikut keselesaan anda.'}</p><span class="stage-tag">PERJALANAN BELAJAR</span><p class="muted">Baca ayat dan maknanya, kenali kalimah dalam konteks, kemudian sambung dari tempat terakhir. Latih pilihan makna ayat dan dengar suara mesin peranti apabila tersedia.</p></section><details class="card guide"><summary>Panduan &amp; Bantuan</summary><p>1. Pilih Dewasa atau Kanak-kanak.<br>2. Tekan Mulakan perjalanan.<br>3. Tekan Mula belajar atau pilih ayat.<br>4. Baca Arab dan makna, kemudian kenali kalimah.<br>5. Tekan Rehat dahulu untuk kembali; gunakan Sambung belajar apabila bersedia.</p><p>Kemajuan ayat dibuka dan kedudukan kalimah disimpan berasingan mengikut profil pada pelayar ini. Ayat dibuka bukan bukti kefahaman, hafalan atau sebutan.</p><p class="muted">Visual dan kandungan asal diluluskan Owner. P2 diluluskan Owner pada notebook dan Android OPPO. P3-B02 termasuk audio diluluskan Owner pada Android OPPO. P4 termasuk audio diluluskan Owner. P5 termasuk audio diluluskan Owner. P6 termasuk audio diluluskan Owner pada Android OPPO. P7 termasuk audio diluluskan Owner. P8 termasuk audio diluluskan Owner pada Android OPPO. P9 UI/audio diluluskan Owner pada OPPO; 24 jam sebenar belum disahkan. P11-B01 reset/Batal diluluskan Owner pada OPPO. B02 termasuk susunan latihan dan semakan manusia diluluskan Owner; adapter AKSI/ATASYA P12 turut diluluskan. P13 diluluskan Owner pada OPPO termasuk audio dan dua profil. Paparan RC02 terpadu dan iPhone menunggu ujian Owner.</p></details><div class="stack">${button('Mulakan perjalanan →','journey','gold')}${button('Lihat semula pembukaan','opening','outline')}</div>`}
function studyButton(label,unitId,style=''){return `<button class="btn ${style}" data-action="study" data-value="${esc(unitId)}">${label}</button>`}
function currentVerse(){return c.verses.find(v=>v.id===activeUnit)||c.verses[0]}
function studyNotice(){const ns=[...learning.notices(),...journeyTools.messages];return ns.length?`<p class="notice" role="status">${ns.some(n=>n.startsWith('OLD_RECORD')||n.includes('PROTECTED')||n.includes('CONTENT_VERSION'))?'Rekod lama dikekalkan dan tidak ditulis ganti. Kemajuan sesi ini mungkin tidak kekal selepas halaman ditutup.':'Kemajuan tidak dapat disimpan sepenuhnya. Anda masih boleh belajar; kekalkan halaman ini terbuka.'}</p>`:''}
function verseCard(v){return `<section class="card verse-card"><span class="eyebrow">ARAB &amp; MAKNA DILULUSKAN</span><p class="muted">Penomboran sumber ini: Basmalah dikira sebagai Ayat 1.</p><p class="arabic" lang="ar" dir="rtl">${esc(v.arabic_candidate)}</p><p class="meaning">${esc(v.translation_candidate_ms)}</p></section>`}
function progressPanel(){const p=learning.getStudyProgress(),summaries=['MCQ','TF','PAIR','ORDER'].map(t=>learning.trainingSummary(t)),answered=summaries.reduce((n,x)=>n+x.answered,0),correct=summaries.reduce((n,x)=>n+x.latestCorrect,0),total=summaries.reduce((n,x)=>n+x.total,0),full=learning.fullSummary().results,ret=learning.retentionSummary().results,latest=full.at(-1),delayed=ret.at(-1),extra=journeyTools.summary();return `<section class="card"><h2>Kemajuan mengikut bukti</h2><p>${p.openedCount}/${p.totalUnits} ayat dibuka · ${p.seenTokenCount}/${p.totalTokens} kalimah dilihat.</p><p>Latihan: ${answered}/${total} unit jawapan pernah dijawab; ${correct}/${total} jawapan terkini betul.</p><p>Ujian gabungan: ${full.length} sesi selesai${latest?' · terkini '+latest.correct+'/'+latest.total:''}.</p><p>Semakan ingatan: ${ret.length} sesi selesai${delayed?' · terkini '+delayed.correct+'/'+delayed.total:''}.</p><p>Susun Ayat: ${extra.sequenceLevels.filter(x=>x.latest?.correct).length}/4 peringkat dengan percubaan terkini betul. Makna → Ayat: ${extra.reverseLatest?extra.reverseLatest.correct+'/'+extra.reverseLatest.total:'belum selesai'}.</p><p class="muted">Aktiviti, jawapan betul dan semakan ingatan direkod berasingan. Ini bukan pengesahan hafalan, sebutan, khusyuk atau keadaan hati.</p></section>`}
function guidedEntry(){const n=journeyTools.recommend(learning);return `<section class="card guidance"><span class="eyebrow">LANGKAH SETERUSNYA</span><h2>${esc(n.label)}</h2><p>Cadangan berdasarkan rekod profil ini. Semua aktiviti tetap boleh dipilih sendiri.</p><button class="btn gold" data-action="guidedNext">${esc(n.label)} →</button></section>`}
function extensionEntry(){const seq=journeyTools.current('sequence'),rev=journeyTools.current('reverse');return `<section class="card"><h2>Susun Ayat lengkap</h2><p>Latihan susunan ayat 2 → 3 → 5 → 7. Teks setiap ayat kekal lengkap; berbeza daripada latihan Susun Kalimah.</p>${seq&&seq.phase!=='RESULT'?'<button class="btn gold" data-action="extraResume" data-value="sequence">Sambung Susun Ayat</button>':''}${button('Pilih peringkat Susun Ayat','sequence','outline')}</section><section class="card"><h2>Makna → Ayat</h2><p>Baca makna lengkap, kemudian pilih ayat Arab yang sepadan. Tujuh soalan; keputusan berasingan daripada ujian gabungan.</p><button class="btn gold" data-action="${rev&&rev.phase!=='RESULT'?'extraResume':'extraStart'}" data-value="reverse">${rev&&rev.phase!=='RESULT'?'Sambung':'Mula'} latihan Makna → Ayat</button></section>`}
function sequenceMenu(){const summary=journeyTools.summary();return `${switcher()}<h1>Susun Ayat lengkap</h1><p>Pilih peringkat, kemudian pilih ayat mengikut susunan dalam surah. Label penomboran dipaparkan selepas Semak. Setiap set dinilai sebagai satu susunan lengkap.</p>${summary.sequenceLevels.map(x=>`<section class="card"><h2>${x.level} ayat</h2><p>${x.attempts} percubaan selesai · terkini ${x.latest?x.latest.correct?'betul':'perlu diulang':'belum dicuba'}.</p><div class="stack">${Array.from({length:c.verses.length-x.level+1},(_,start)=>`<button class="btn outline" data-action="sequenceStart" data-value="${x.level}:${start}">Ayat ${start+1}–${start+x.level}</button>`).join('')}</div></section>`).join('')}${button('Kembali ke perjalanan','journey','outline')}`}
function extensionView(kind){const s=journeyTools.current(kind),title=kind==='sequence'?'Susun Ayat lengkap':'Makna → Ayat';if(!s)return kind==='sequence'?sequenceMenu():`${switcher()}<h1>${title}</h1>${extensionEntry()}${button('Kembali ke perjalanan','journey','outline')}`;if(s.paused&&s.phase!=='RESULT')return `${switcher()}<h1>${title} direhatkan</h1><button class="btn gold" data-action="extraResume" data-value="${kind}">Sambung latihan</button>${button('Kembali ke perjalanan','journey','outline')}`;if(s.phase==='RESULT'){const rec=s.receipts.filter(x=>x.correct).length;return `${switcher()}<h1>${title} selesai</h1><section class="card"><p>${rec}/${s.plan.length} ${kind==='sequence'?'susunan lengkap':'jawapan'} betul.</p><p>Keputusan latihan tambahan; tidak ditambah kepada 35 markah ujian gabungan dan bukan bukti hafalan atau sebutan.</p></section>${kind==='sequence'?button('Pilih peringkat lain','sequenceMenu','outline'):'<button class="btn gold" data-action="extraStart" data-value="reverse">Cuba latihan baharu</button>'}${button('Kembali ke perjalanan','journey','outline')}`}
const item=s.plan[s.cursor],checked=s.phase==='FEEDBACK',verse=id=>c.verses.find(v=>v.id===id),arabic=id=>`<p class="arabic" lang="ar" dir="rtl">${esc(verse(id).arabic_candidate)}</p>`,picked=kind==='sequence'?s.draft:[];return `${switcher()}<span class="eyebrow">${title} · ${s.cursor+1}/${s.plan.length}</span><h1>${title}</h1>${kind==='sequence'?`<p>Pilih ${item.answer.length} ayat mengikut urutan bacaan. Baca kad terpilih dari atas ke bawah.</p><section class="card"><h2>Susunan anda · ${picked.length}/${item.answer.length}</h2>${picked.map(id=>arabic(id)).join('')||'<p>Belum memilih ayat.</p>'}<p>Ini jawapan anda; belum disahkan sebelum Semak.</p></section><div class="lesson-nav"><button class="btn outline" data-action="extraUndo" ${checked||!picked.length?'disabled':''}>Undur satu</button><button class="btn outline" data-action="extraClear" ${checked||!picked.length?'disabled':''}>Mula semula susunan</button></div>`:`<section class="card"><h2>Makna lengkap untuk dipadankan</h2><p class="meaning">${esc(verse(item.target).translation_candidate_ms)}</p></section><p>Pilih satu ayat Arab lengkap.</p>`}<div class="stack">${item.choices.map(id=>`<section class="card"><button class="btn answer ${(kind==='sequence'?picked.includes(id):s.draft===id)?'selected':''}" data-action="extraPick" data-value="${esc(id)}" ${checked||kind==='sequence'&&picked.includes(id)?'disabled':''}>${arabic(id).replaceAll('<p class="arabic"','<span class="arabic"').replaceAll('</p>','</span>')}<span>${kind==='sequence'&&picked.includes(id)?'Telah dipilih':'Pilih ayat'}</span></button>${audioControls(verse(id).audio_id)}</section>`).join('')}</div>${checked?`<section class="card feedback" role="status"><h2>${s.receipts[s.cursor].correct?'Betul.':'Mari lihat semula.'}</h2><h3>Jawapan rujukan</h3>${(kind==='sequence'?item.answer:[item.answer]).map(id=>`<p>Ayat ${esc(verse(id).verse_key.split(':')[1])}</p>${verseCard(verse(id))}${audioControls(verse(id).audio_id)}`).join('')}</section><button class="btn gold" data-action="extraNext">${s.cursor===s.plan.length-1?'Lihat keputusan':'Soalan seterusnya'}</button>`:`<button class="btn gold" data-action="extraCheck" ${kind==='sequence'?picked.length!==item.answer.length?'disabled':'':s.draft===null?'disabled':''}>Semak jawapan</button>`}${button('Rehat dahulu · simpan latihan','journey','outline')}`}
function reflectionView(){const notes=[['read','Baca semula ayat Arab dan maknanya.'],['meaning','Pilih satu ayat untuk dibaca dan difahami bersama konteksnya.'],['practice',profile==='kid'?'Bincangkan pembelajaran ini bersama ibu bapa atau guru.':'Luangkan masa mengulang bacaan dan makna dalam rutin pembelajaran anda.']],saved=journeyTools.state().reflection;return `${switcher()}<h1>Hayati & amalkan</h1><p>Ruang renungan pembelajaran. Panduan aktiviti ini bukan terjemahan atau tafsir baharu, diwarisi daripada P13 yang diluluskan Owner; paparan terpadu ini masih calon ujian.</p><section class="card"><h2>Langkah pilihan anda</h2>${notes.map(([id,text])=>`<p>${esc(text)}</p><button class="btn outline" data-action="reflectToggle" data-value="${id}" aria-pressed="${saved[id]===true}">${saved[id]?'Tandaan kendiri: sudah dibuat · batal tanda':'Tandakan sendiri apabila dibuat'}</button>`).join('')}<p class="muted">Tandaan ini laporan kendiri sahaja; tiada markah, penilaian ibadah atau pengesahan keadaan hati.</p></section>${button('Bacaan penuh','fullReading')}${button('Sumber & bantuan','sources','outline')}${button('Kembali ke perjalanan','journey','outline')}`}
function exportProfileRecord(){return {...learning.exportRecord(),journeyEnhancements:journeyTools.state(),journeyEnhancementNotices:[...new Set(journeyTools.messages)]}}
function runGuidedNext(){const n=journeyTools.recommend(learning);if(n.type==='core'){journeyTools.pause();if(n.mode==='full'){learning.resumeFull();go('practice/FULL')}else if(n.mode==='retention'){learning.resumeRetention();go('practice/RETENTION')}else if(n.mode==='retry'){learning.resumeRetry(n.scope);go('practice/RETRY/'+n.scope)}else{learning.resumeTraining(n.trainingType);go('practice/'+n.trainingType)}}else if(n.type==='extension'){learning.pauseTraining();journeyTools.resume(n.kind);go(n.kind)}else if(n.type==='retry'){learning.startRetry(n.scope);go('practice/RETRY/'+n.scope)}else if(n.type==='study'){go('learn/'+n.id+'/0')}else if(n.type==='training'){learning.startTraining(n.trainingType);go('practice/'+n.trainingType)}else if(n.type==='full'){learning.startFull();go('practice/FULL')}else if(n.type==='retention'){learning.startRetention();go('practice/RETENTION')}else if(n.type==='newReverse'){journeyTools.start('reverse');go('reverse')}else if(n.type==='sequence'){go('sequenceMenu')}else go('fullReading')}

function phaseEvidence(key){const p=learning.getStudyProgress();if(key==='learn')return p.openedCount+'/'+p.totalUnits+' ayat dibuka · '+p.seenTokenCount+'/'+p.totalTokens+' kalimah dilihat';if(key==='practice'){const summaries=['MCQ','TF','PAIR','ORDER'].map(t=>learning.trainingSummary(t));return summaries.reduce((n,x)=>n+x.answered,0)+'/'+summaries.reduce((n,x)=>n+x.total,0)+' unit jawapan latihan asal pernah dijawab';}if(key==='reinforce')return ['training','full','retention'].reduce((n,scope)=>n+learning.retrySummary(scope).needs.length,0)+' unit jawapan terkini salah dalam tiga skop asal';if(key==='full'){const results=learning.fullSummary().results;return results.length+' sesi selesai'+(results.length?' · terkini '+results.at(-1).correct+'/'+results.at(-1).total:' · 35 unit markah');}if(key==='retention'){const st=learning.retentionStatus(),results=learning.retentionSummary().results;return results.length+' sesi selesai · '+(!st.schedule?'lengkapkan ujian gabungan dahulu':st.eligible?'waktu semakan tersedia':st.reason==='CLOCK_ROLLBACK'?'semak jam peranti':'menunggu waktu kelayakan');}return ['read','meaning','practice'].filter(id=>journeyTools.state().reflection[id]===true).length+'/3 tandaan kendiri · tanpa markah';}
function learningMap(){const progress=learning.getStudyProgress(),last=progress.currentStudy;return `<section class="card"><span class="eyebrow">KEDUDUKAN BELAJAR</span><h2>${last?'Sambung Ayat '+esc(c.verses.find(v=>v.id===last.ayatId).verse_key.split(':')[1]):'Mulakan dengan Ayat 1'}</h2><p>${last?'Kedudukan terakhir profil ini telah disimpan.':'Belajar satu ayat pada satu masa, mengikut kemampuan anda.'}</p>${last?button('Sambung belajar →',last.view+'/'+last.ayatId+'/'+last.tokenIndex):studyButton('Mula belajar →',c.verses[0].id)}<div class="study-progress"><progress max="${progress.totalUnits}" value="${progress.openedCount}" aria-label="Ayat telah dibuka"></progress><p>${progress.openedCount} daripada ${progress.totalUnits} ayat telah dibuka · ${progress.seenTokenCount}/${progress.totalTokens} kalimah dilihat.</p></div><p class="muted">Rekod ini menunjukkan kandungan yang telah dibuka. Ayat dibuka berbeza daripada keputusan latihan pilihan makna.</p></section><section class="stack"><h2>Peta ${c.verses.length} ayat</h2><div class="unit-list">${c.verses.map(v=>`<section class="unit unit-link"><div><strong>Ayat ${esc(v.verse_key.split(':')[1])}</strong><small>${progress.openedUnitIds.includes(v.id)?'Telah dibuka':'Belum dibuka'}</small></div>${studyButton('Belajar ayat',v.id,'outline')}</section>`).join('')}</div></section>${button('Bacaan penuh','fullReading','outline')}`;}
function phaseContent(key){if(key==='learn')return learningMap();if(key==='practice')return flashEntry()+['MCQ','TF','PAIR','ORDER'].map(t=>practiceEntry(t)).join('')+extensionEntry();if(key==='reinforce')return ['training','full','retention'].map(scope=>retryEntry(scope)).join('');if(key==='full')return fullEntry();if(key==='retention')return retentionEntry();return `<section class="card"><h2>Hayati & amalkan</h2><p>Gunakan panduan aktiviti pembelajaran yang diwarisi daripada P13. Tandaan kendiri disimpan berasingan daripada skor latihan.</p>${button('Buka Hayati & amalkan','reflect','gold')}${button('Bacaan penuh','fullReading','outline')}</section>`;}
function journeyContext(){return {profile,switcher:switcher(),notice:studyNotice(),guidance:guidedEntry(),progress:progressPanel(),counts:`<div class="stats"><div class="stat"><strong>${c.tokens.length}</strong><span>Kalimah</span></div><div class="stat"><strong>${c.verses.length}</strong><span>Ayat</span></div><div class="stat"><strong>1</strong><span>Surah</span></div></div>`,evidence:phaseEvidence,content:phaseContent};}
function journey(){return window.ASKUnifiedJourney.home(journeyContext())}
function stageView(){return window.ASKUnifiedJourney.stage(journeyContext(),stageKey)}
function stageNavigation(){const active=window.ASKUnifiedJourney.contextFor(route,trainingType,retryScope,stageKey);return window.ASKUnifiedJourney.navigation(active)}
function stageReturn(){const active=window.ASKUnifiedJourney.contextFor(route,trainingType,retryScope,stageKey),stage=window.ASKUnifiedJourney.steps.find(x=>x.id===active);return stage&&!['stage','journey'].includes(route)?button('Kembali ke fasa '+stage.short,'stage/'+stage.id,'outline'):'';}

function learn(){const v=currentVerse(),index=c.verses.indexOf(v),ts=c.tokens.filter(t=>t.ayat_id===v.id),image=assets['learn-'+(index+1)];return `${switcher()}<div class="lesson-heading"><span class="eyebrow">AYAT ${index+1} DARIPADA ${c.verses.length}</span><h1>${profile==='kid'?'Baca dan fahami bersama':'Fahami ayat ini'}</h1><p>Satu ayat, satu langkah memahami makna.</p></div>${studyNotice()}${image?`<figure class="lesson-art"><img src="${esc(image.path)}" alt="Ilustrasi asal Al-Fatihah Ayat ${index+1} yang diluluskan" decoding="async"><figcaption>Visual pembelajaran asal</figcaption><button class="btn outline" data-action="zoomImage" data-value="learn-${index+1}">Besarkan imej ayat</button></figure>`:''}${verseCard(v)}${audioControls(v.audio_id)}<section class="card"><h2>${profile==='kid'?'Jom kenali kalimah':'Kalimah dalam konteks'}</h2><p>${ts.length} kalimah dalam ayat ini. Lihat glos pembelajaran bersama makna ayat penuh.</p>${button('Kenali kalimah →','words/'+v.id+'/'+activeToken,'outline')}</section><div class="lesson-nav">${index>0?studyButton('← Ayat sebelumnya',c.verses[index-1].id,'outline'):''}${index<c.verses.length-1?studyButton('Ayat seterusnya →',c.verses[index+1].id):button('Lihat perjalanan anda →','readingEnd','gold')}</div><p class="muted">Membuka ayat direkod sebagai aktiviti belajar, bukan pengesahan kefahaman, hafalan atau sebutan.</p><div class="stack">${button('Rehat dahulu · simpan kedudukan','journey','outline')}${button('Kembali ke peta ayat','journey','outline')}</div>`}
function words(){const v=currentVerse(),ts=c.tokens.filter(t=>t.ayat_id===v.id),t=ts[activeToken]||ts[0];return `${switcher()}<div class="lesson-heading"><span class="eyebrow">AYAT ${esc(v.verse_key.split(':')[1])} · KALIMAH ${activeToken+1}/${ts.length}</span><h1>${profile==='kid'?'Jom kenali kalimah':'Kalimah dalam konteks'}</h1></div>${studyNotice()}<section class="card token-card"><p class="arabic" lang="ar" dir="rtl">${esc(t.arabic_exact_slice)}</p><p class="meaning">${esc(t.gloss_candidate_ms)}</p><p class="muted">${esc(t.context_note)}</p></section>${audioControls(t.id)}<div class="lesson-nav">${activeToken>0?button('← Kalimah sebelumnya','words/'+v.id+'/'+(activeToken-1),'outline'):''}${activeToken<ts.length-1?button('Kalimah seterusnya →','words/'+v.id+'/'+(activeToken+1)):button('Kembali ke ayat →','learn/'+v.id)}</div><details class="card guide"><summary>Konteks ayat penuh</summary>${verseCard(v)}${audioControls(v.audio_id)}</details><div class="stack">${button('Kembali ke ayat','learn/'+v.id,'outline')}${button('Rehat dahulu · simpan kedudukan','journey','outline')}</div>`}
function readingEnd(){const p=learning.getStudyProgress();return `${switcher()}<section class="hero"><span class="eyebrow">PERJALANAN MEMBACA</span><h1>${p.allUnitsOpened?'Semua ayat telah dibuka.':'Teruskan mengikut kemampuan.'}</h1><p>${p.openedCount} daripada ${p.totalUnits} ayat telah dibuka oleh profil ini.</p></section><section class="card"><h2>Satu langkah yang baik</h2><p>Anda boleh membaca semula ayat dan makna atau mengulang kalimah. Rekod membuka kandungan tidak mengesahkan penguasaan atau hafalan.</p><p class="muted">Cuba latihan pilihan makna daripada peta perjalanan. Keputusan ini tidak mengesahkan hafalan atau sebutan.</p></section>${button('Kembali ke perjalanan','journey','gold')}${studyButton('Baca semula Ayat 1',c.verses[0].id,'outline')}`}
const refs=Object.fromEntries(c.refs.map(x=>[x.id,x.value]));
function updateAudioUI(){if(!audio)return;const s=audio.status();for(const el of root.querySelectorAll('[data-audio-status]')){const current=s.targetId===el.dataset.audioStatus;el.textContent=current?(({idle:'Tekan Dengar untuk mencuba suara peranti.',preparing:'Menyediakan suara…',playing:'Sedang dimainkan…',ended:'Pelayar melaporkan audio selesai.',blocked:'Tekan Dengar untuk memulakan.',error:'Audio belum berjaya. Cuba semula atau teruskan membaca.',unavailable:'Suara peranti tidak tersedia. Teruskan membaca.'})[s.phase]||'Audio dihentikan.'):(s.phase==='stopped'?'Audio dihentikan.':'Tekan Dengar untuk mencuba suara peranti.');}}
function audioControls(id){const token=c.tokens.find(t=>t.id===id),v=c.verses.find(v=>v.audio_id===id),label=token?'Dengar kalimah':v?'Dengar ayat penuh':'Dengar';const context=token?'Ayat '+c.verses.find(v=>v.id===token.ayat_id).verse_key.split(':')[1]+' · kalimah '+(c.tokens.filter(t=>t.ayat_id===token.ayat_id).findIndex(t=>t.id===id)+1):v?'Ayat '+v.verse_key.split(':')[1]:'';return `<section class="card audio-controls" aria-label="Suara ${esc(context)}"><button class="btn" data-action="audio" data-value="${esc(id)}" aria-label="${label} · ${esc(context)}">${label}</button><button class="btn outline" data-action="stopAudio">Hentikan audio</button><p data-audio-status="${esc(id)}" role="status" aria-live="polite">Tekan Dengar untuk mencuba suara peranti.</p><p class="muted">Suara mesin peranti; bukan rakaman qari. Ketersediaan dan sebutan bergantung pada peranti. Tiada markah diberikan kerana mendengar.</p></section>`}
function flashEntry(){const current=learning.currentFlash();return `<section class="card"><h2>Kad Imbas</h2><p>${learning.flashCards().length} kad ayat dan makna. Cuba ingat makna, kemudian buka untuk menyemak.</p><p class="muted">Membuka makna tidak memberi markah penguasaan.</p>${button(current?'Sambung Kad Imbas':'Mula Kad Imbas','flash/'+(current?.item.id||learning.flashCards()[0].id),'gold')}</section>`}
function flash(){const current=learning.currentFlash(),i=current.item,cards=learning.flashCards(),n=cards.findIndex(x=>x.id===i.id),v=c.verses.find(v=>v.id===i.ayat_ids[0]);return `${switcher()}<span class="eyebrow">KAD ${n+1}/${cards.length} · AYAT ${esc(v.verse_key.split(':')[1])}</span><h1>Kad Imbas</h1>${studyNotice()}<section class="card"><p class="arabic" lang="ar" dir="rtl">${esc(refs[i.front_ref])}</p><p>Cuba ingat makna ayat ini sebelum membuka jawapan.</p></section>${audioControls(v.audio_id)}<button class="btn gold" data-action="flashReveal" aria-expanded="${current.revealed}">${current.revealed?'Tutup makna':'Buka makna'}</button>${current.revealed?`<section class="card flash-meaning" role="status"><h2>Makna ayat</h2><p class="meaning">${esc(refs[i.back_ref])}</p></section>`:''}<p class="muted">Membaca atau membuka makna tidak mengesahkan kefahaman, hafalan atau sebutan.</p><div class="lesson-nav">${n>0?button('← Kad sebelumnya','flash/'+cards[n-1].id,'outline'):''}${n<cards.length-1?button('Kad seterusnya →','flash/'+cards[n+1].id):button('Kembali ke perjalanan','journey','gold')}</div>${button('Rehat · simpan Kad Imbas','journey','outline')}`}
function fullEntry(){const t=learning.fullSession(),p=learning.fullSummary(),last=p.results.at(-1);return `<section class="card"><h2>Ujian gabungan</h2><p>${p.itemCount} soalan/set · ${p.total} unit markah. Pilihan makna, Benar/Palsu, Padanan dan Susun Kalimah digabungkan. Kad Imbas ialah persediaan tanpa markah.</p>${last?`<p>Keputusan sesi terakhir: ${last.correct}/${last.total}.</p>`:''}<p class="muted">Audio dan pembetulan selepas Semak tersedia seperti baseline. Keputusan ini tidak mengesahkan hafalan atau sebutan. Semakan ingatan mempunyai syarat masa berasingan pada bahagian 24 jam.</p><button class="btn gold" data-action="${t&&t.session.phase!=='RESULT'?'resumeFull':'startFull'}">${t&&t.session.phase!=='RESULT'?'Sambung ujian gabungan':'Mula ujian gabungan'}</button></section>`}
function timeLabel(ms){try{return new Date(ms).toLocaleString('ms-MY',{dateStyle:'medium',timeStyle:'short'})}catch{return String(ms)}}
function retentionEntry(){const p=learning.retentionSummary(),t=learning.retentionSession(),last=p.results.at(-1),minutes=p.remainingMs===null?null:Math.ceil(p.remainingMs/60000),reason=({FULL_REQUIRED:'Lengkapkan ujian gabungan dahulu untuk merekodkan jadual 24 jam.',NO_RETRY_TARGETS:'Tiada jawapan terkini salah dalam skop ini. Kembali ke perjalanan.',NOT_DUE:'Belum cukup 24 jam. Baki anggaran '+Math.floor((minutes||0)/60)+' jam '+((minutes||0)%60)+' minit.',CLOCK_INVALID:'Masa peranti tidak dapat dibaca. Semak tetapan masa.',CLOCK_ROLLBACK:'Masa peranti lebih awal daripada rekod terdahulu. Semak masa peranti sebelum meneruskan.',READY:'Masa kelayakan telah tiba mengikut jam peranti.'})[p.reason];return `<section class="card"><h2>Semakan ingatan 24 jam</h2><p role="status">${reason}</p>${p.schedule?`<p>Ujian pertama selesai: ${esc(timeLabel(p.schedule.startedAt))}<br>Layak mulai: ${esc(timeLabel(p.schedule.dueAt))}</p>`:''}<p>${p.itemCount} soalan/set · ${p.total} unit markah. Rekod berasingan daripada latihan dan ujian gabungan.</p>${last?`<p>Keputusan semakan terakhir: ${last.correct}/${last.total}.</p>`:''}<p class="muted">Kelayakan berdasarkan jam dan rekod pada pelayar/peranti ini. Kekalkan masa automatik; ini bukan pengesahan masa pelayan. Audio dan pembetulan tersedia seperti baseline.</p><button class="btn gold" data-action="${t&&t.session.phase!=='RESULT'?'resumeRetention':'startRetention'}" ${p.eligible?'':'disabled'}>${t&&t.session.phase!=='RESULT'?'Sambung semakan ingatan':'Mula semakan ingatan 24 jam'}</button><button class="btn outline" data-action="refreshEligibility">Semak masa kelayakan</button></section>`}
const scopeNames={training:'Latihan',full:'Ujian gabungan',retention:'Semakan ingatan'};
function retryEntry(scope){const p=learning.retrySummary(scope),t=learning.retrySession(scope),resume=t&&t.session.phase!=='RESULT',gate=scope!=='retention'||learning.retentionStatus().eligible;return `<section class="card"><h2>Pengukuhan · ${scopeNames[scope]}</h2><p>${p.needs.length} unit jawapan terkini salah. ${p.itemCount} soalan/set perlu diulang.</p><p class="muted">Jawapan belum dicuba bukan salah. Jika satu pasangan salah, seluruh set Padanan diulang seperti baseline. Rekod pertama kekal; jawapan terkini dikemas kini dalam skop asal.</p><button class="btn gold" data-action="${resume?'resumeRetry':'startRetry'}" data-value="${scope}" ${gate&&(resume||p.itemCount)?'':'disabled'}>${!gate?'Menunggu masa kelayakan':resume?'Sambung pengukuhan':p.itemCount?'Mula pengukuhan':'Tiada jawapan salah'}</button>${gate?'':'<p>Pengukuhan semakan ingatan masih tertakluk kelayakan 24 jam.</p>'}</section>`}
function fullReading(){return `${switcher()}<h1>Bacaan penuh Al-Fatihah</h1><p>Baca mengikut susunan ayat. Mendengar atau membaca tidak memberi markah.</p>${audioControls('FATIHAH-AUD-FULL')}${c.verses.map(v=>`<h2>Ayat ${esc(v.verse_key.split(':')[1])}</h2>${verseCard(v)}${audioControls(v.audio_id)}`).join('')}${button('Kembali ke perjalanan','journey','outline')}`}
function sources(){return `${switcher()}<h1>Sumber &amp; bantuan</h1><section class="card"><h2>Kandungan diluluskan</h2><p>Rujukan dan teks sumber dikekalkan. Owner telah mengesahkan semakan manusia TTS, glos dan bukti atribusi/edisi terjemahan B02 lengkap. Pengenal edisi khusus tidak dinyatakan dalam mesej kelulusan; metadata sumber asal dikekalkan untuk jejak audit.</p><p>Bentuk Arab digital termasuk tatweel dikekalkan tepat untuk menjaga hash; carian yang menormalkan teks perlu pemetaan berasingan, bukan mengubah teks sumber.</p><p>Tujuh ayat dan transkripsi terjemahan daripada bahan Smart Quran pengguna, dengan rujukan digital Quran.com. Glos kalimah dikekalkan bersama konteks ayat.</p><p><a href="https://www.islam.gov.my/ms/quran-hadith/smart-quran" target="_blank" rel="noopener">Rujukan Smart Quran JAKIM</a></p><p>Rujukan ini diwarisi daripada baseline; pautan luar tidak menentukan status kelulusan binaan.</p>${c.verses.map(v=>`<p>Ayat ${esc(v.verse_key)} · Arab: ${esc(v.arabic_source)} ${esc(v.arabic_source_location)} · Makna: ${esc(v.translation_source)} · Kelulusan: ${esc(v.approval_ref)}</p>`).join('')}</section><section class="card"><h2>Panduan semasa</h2><p>Gunakan Besarkan teks pada pengepala. Imej asal boleh dibesarkan melalui butang pada imej atau galeri di bawah. Rekod calon terpadu berasingan; tiada import automatik daripada binaan terdahulu.</p><p>Pilih profil, belajar ayat/kalimah, Kad Imbas atau empat latihan. Ujian gabungan dinilai berasingan. Pengukuhan mengulang jawapan terkini salah dalam skop yang dipilih.</p><p>Semakan ingatan dikira 24 jam selepas ujian gabungan pertama selesai mengikut masa peranti. Jangan tukar jam untuk bukti masa sebenar. Profil dan pelayar menyimpan rekod berasingan.</p><p>Suara mesin peranti, bukan rakaman qari. Tekan Dengar sendiri, semak kelantangan media dan suara Arab peranti. Untuk iPhone, gunakan halaman HTTPS dalam Safari; kelulusan OPPO tidak mengesahkan iPhone.</p><p>Kanak-kanak digalakkan belajar bersama ibu bapa atau guru. Bacaan/audio/klik tidak mengesahkan hafalan, sebutan atau keadaan hati.</p></section>${assetGallery()}${button('Lihat rekod & eksport','records')}${button('Kembali ke perjalanan','journey','outline')}`}
function recordsPage(){const x=exportProfileRecord(),p=x.record;return `${switcher()}<h1>Rekod profil ini</h1><p class="notice">RC02 terpadu menggunakan rekod percubaan berasingan; rekod P13 dan RC02 terdahulu kekal. Rekod keluaran terdahulu tidak diimport atau dipadam.</p><section class="card"><p>Binaan ${esc(r.buildId)} · ${esc(profile)}</p><p>${learning.getStudyProgress().openedCount}/${c.verses.length} ayat dibuka. ${p.results.length} sesi latihan/ujian selesai.</p><p>Eksport memuatkan rekod profil aktif sahaja. Fail disimpan pada peranti; tiada penghantaran automatik.</p><button class="btn gold" data-action="exportRecord">Muat turun rekod JSON</button><details><summary>Lihat / salin rekod JSON</summary><textarea aria-label="Rekod JSON profil aktif" readonly rows="14">${esc(JSON.stringify(x,null,2))}</textarea></details></section>${resetControls()}${button('Kembali ke perjalanan','journey','outline')}`}
function resetControls(){const label=profile==='adult'?'Dewasa':'Kanak-kanak';return resetPending===profile?`<section class="card reset-confirm" role="alert"><h2>Sahkan padam rekod ${label}</h2><p>Ini akan memadam rekod belajar, jawapan/skor, kad imbas dan jadual 24 jam profil ${label} untuk aplikasi ini dalam pelayar ini. Profil satu lagi tidak dipadam. Jika perlu, eksport rekod dahulu; aplikasi belum menyediakan import semula.</p><div class="stack"><button class="btn outline" data-action="resetCancel">Batal · kekalkan rekod</button><button class="btn danger" data-action="resetConfirm" data-value="${profile}">Ya, padam rekod ${label}</button></div></section>`:`<section class="card"><h2>Urus rekod ${label}</h2><p>Padam hanya jika mahu bermula semula. Pengesahan diperlukan pada langkah seterusnya.</p><button class="btn outline" data-action="resetAsk">Padam rekod profil ini…</button></section>`}
function assetGallery(){return `<section class="card"><h2>Imej asal</h2><p>Tekan imej untuk melihat lebih besar. Bait/aset asal dikekalkan.</p><div class="asset-gallery">${Object.values(assets).map(a=>`<button class="image-link" data-action="zoomImage" data-value="${esc(a.id)}"><img loading="lazy" decoding="async" src="${esc(a.path)}" alt="Imej asal ${esc(a.id)}"><span>Lihat ${esc(a.id)}</span></button>`).join('')}</div></section>`}
function zoomPanel(){if(!zoomTarget)return '';const a=assets[zoomTarget];return `<dialog id="asset-dialog" aria-label="Imej asal diperbesar"><div class="zoom-toolbar"><h2>Imej asal · ${esc(a.id)}</h2><button class="btn outline" data-action="zoomClose">Tutup imej</button></div><div class="lesson-nav"><button class="btn outline" data-action="zoomOut" ${zoomScale<=100?'disabled':''}>Kecilkan imej</button><button class="btn outline" data-action="zoomIn" ${zoomScale>=250?'disabled':''}>Besarkan imej</button><button class="btn outline" data-action="zoomFit">Muat skrin</button></div><p role="status">Pembesaran ${zoomScale}% · tatal dalam imej untuk melihat bahagian lain.</p><div class="image-viewport"><img src="${esc(a.path)}" alt="Imej asal ${esc(a.id)} diperbesar" style="width:${zoomScale}%;max-width:none;height:auto"></div></dialog>`}
function mountZoom(){if(!zoomTarget)return;const dialog=document.getElementById('asset-dialog');if(dialog?.showModal){dialog.showModal();dialog.addEventListener('cancel',e=>{e.preventDefault();closeZoom()},{once:true})}else dialog?.setAttribute?.('open','');}
function closeZoom(){const id=zoomTarget,scroll=zoomReturnScroll;zoomTarget=null;render();window.scrollTo(0,scroll);const opener=[...root.querySelectorAll('button[data-action="zoomImage"]')].find(b=>b.dataset.value===id);opener?.focus?.({preventScroll:true})}
function downloadRecord(){const x=exportProfileRecord(),blob=new Blob([JSON.stringify(x,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=r.buildId+'-'+profile+'-rekod.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);notice='Fail rekod diminta daripada pelayar. Jika muat turun tidak tersedia, buka Lihat / salin rekod JSON.';render()}
function practiceEntry(type=trainingType){if(type==='FULL')return fullEntry();if(type==='RETENTION')return retentionEntry();if(type==='RETRY')return retryEntry(retryScope);const t=learning.training(type),p=learning.trainingSummary(type),title=type==='ORDER'?'Susun Kalimah':type==='PAIR'?'Padanan':type==='TF'?'Benar/Palsu':'pilihan makna';return `<section class="card"><h2>Latihan ${title}</h2><p>${p.latestCorrect}/${p.total} jawapan terkini betul · ${p.answered}/${p.total} ${type==='PAIR'?'pasangan':'soalan'} pernah dijawab.${type==='PAIR'?' Dibahagikan kepada '+p.sets+' set.':''}</p><p class="muted">Latihan kefahaman sahaja; belum ujian lengkap atau semakan ingatan 24 jam.</p>${t&&t.session.phase!=='RESULT'?`<button class="btn gold" data-action="resumeTraining" data-value="${type}">Sambung latihan ${title}</button>`:`<button class="btn gold" data-action="startTraining" data-value="${type}">Mula latihan ${title}</button>`}</section>`}
function orderPanel(t,checked){const {session:s,item:i}=t;const v=c.verses.find(v=>v.id===i.ayat_ids[0]);return `<p>Ayat ${esc(v.verse_key.split(':')[1])} · ${s.draft.length}/${i.token_refs.length} kalimah dipilih. Baca susunan dari kanan ke kiri.</p><section class="card"><h2>Susunan anda</h2><p class="arabic order-sequence" lang="ar" dir="rtl">${s.draft.map(id=>esc(refs[id])).join(' ')||'…'}</p><p class="muted">Susunan ini ialah jawapan anda dan belum disahkan betul sebelum Semak.</p>${s.draft.length?audioControls(s.draft.at(-1)):''}</section><div class="lesson-nav"><button class="btn outline" data-action="orderUndo" ${checked||!s.draft.length?'disabled':''}>Undur satu</button><button class="btn outline" data-action="orderClear" ${checked||!s.draft.length?'disabled':''}>Mula semula susunan</button></div><h2>Pilih kalimah seterusnya</h2><div class="stack">${s.orders[i.id].token_refs.map(id=>`<section class="card"><button class="btn answer" data-action="orderPick" data-value="${esc(id)}" ${checked||s.draft.includes(id)?'disabled':''}><span class="arabic" lang="ar" dir="rtl">${esc(refs[id])}</span><span>${s.draft.includes(id)?'Telah dipilih':'Pilih kalimah'}</span></button>${audioControls(id)}</section>`).join('')}</div>`}
function pairPanel(t,checked){const {session:s,item:i}=t;const selected=i.left_refs.includes(pairLeft)?pairLeft:null;return `<section class="card"><p role="status">${Object.keys(s.draft).length}/${i.left_refs.length} pasangan dipilih.</p><p>Pilih ayat, kemudian maknanya. Lengkapkan semua pasangan sebelum Semak. Gunakan Buang pasangan untuk menukar pilihan.</p></section><h2>1. Pilih ayat</h2><div class="stack">${s.orders[i.id].left_refs.map(ref=>{const v=c.verses.find(v=>v.id+'-AR'===ref);return `<section class="card"><button class="btn answer ${selected===ref?'selected':''}" data-action="pairLeft" data-value="${esc(ref)}" aria-pressed="${selected===ref}" ${checked?'disabled':''}><span>Ayat ${esc(v.verse_key.split(':')[1])}${s.draft[ref]?' · Dipadankan':''}</span><span class="arabic" lang="ar" dir="rtl">${esc(refs[ref])}</span></button>${audioControls(v.audio_id)}</section>`}).join('')}</div><h2>2. Pilih makna</h2><div class="stack">${s.orders[i.id].right_refs.map(ref=>{const used=Object.entries(s.draft).find(([l,r])=>r===ref)?.[0];return `<button class="btn answer" data-action="pairRight" data-value="${esc(ref)}" ${checked||!selected||(used&&used!==selected)?'disabled':''}>${esc(refs[ref])}${used?' · Telah dipadankan':''}</button>`}).join('')}</div><section class="card"><h2>Pasangan anda</h2>${Object.entries(s.draft).map(([l,r])=>`<p><strong>Ayat ${esc(c.verses.find(v=>v.id+'-AR'===l).verse_key.split(':')[1])}</strong> · ${esc(refs[r])}</p>${checked?'':`<button class="btn outline" data-action="unpair" data-value="${esc(l)}">Buang pasangan</button>`}`).join('')||'<p>Belum ada pasangan dipilih.</p>'}</section>`}
function practice(){const retry=trainingType==='RETRY',retention=trainingType==='RETENTION',combined=trainingType==='FULL',t=retry?learning.retrySession(retryScope):retention?learning.retentionSession():combined?learning.fullSession():learning.training(trainingType);if(!t)return `<h1>${retention?'Semakan ingatan 24 jam':combined?'Ujian gabungan':'Latihan pilihan makna'}</h1>${practiceEntry()}`;const {session:s,item:i}=t;if(s.paused)return `<h1>${retention?'Semakan ingatan direhatkan':combined?'Ujian gabungan direhatkan':'Latihan direhatkan'}</h1>${practiceEntry()}${button('Kembali ke perjalanan','journey','outline')}`;if(s.phase==='RESULT'){const result=(retry?learning.retrySummary(retryScope):retention?learning.retentionSummary():combined?learning.fullSummary():learning.trainingSummary(trainingType)).results.find(x=>x.sessionId===s.id);return `<h1>${retry?'Pengukuhan selesai':retention?'Semakan ingatan selesai':combined?'Ujian gabungan selesai':'Latihan selesai'}</h1><section class="card"><p>${result.correct}/${result.total} jawapan betul dalam sesi ini.</p><p>Ini keputusan ${retry?'pengukuhan '+scopeNames[retryScope]:retention?'semakan ingatan':combined?'ujian gabungan':'latihan'} ${retry||retention||combined?'':trainingType==='ORDER'?'Susun Kalimah':trainingType==='PAIR'?'Padanan':trainingType==='TF'?'Benar/Palsu':'pilihan makna'}, bukan pengesahan hafalan, sebutan atau penguasaan keseluruhan.</p></section>${retry?retryEntry(retryScope):`<button class="btn" data-action="${retry?'startRetry':retention?'startRetention':combined?'startFull':'startTraining'}" data-value="${retry?retryScope:trainingType}">${retry?'Cuba pengukuhan seterusnya':retention?'Cuba semakan baharu':combined?'Cuba ujian baharu':'Cuba latihan baharu'}</button>`}${combined?'<p class="muted">Jadual 24 jam dikira daripada ujian penuh pertama selesai. Lihat masa kelayakan pada perjalanan.</p>':''}${button('Kembali ke perjalanan','journey','outline')}`;}const checked=s.phase==='FEEDBACK',receipt=learning.diagnostics().current.profiles[profile].receipts[s.id+'/'+i.id];return `${switcher()}<span class="eyebrow">${retry?'PENGUKUHAN · '+scopeNames[retryScope]:retention?'SEMAKAN INGATAN':combined?'UJIAN GABUNGAN':'LATIHAN'} ${s.cursor+1}/${s.itemIds.length}</span><h1>${i.type==='ORDER'?'Susun kalimah ayat':i.type==='PAIR'?'Padankan ayat dan makna':i.type==='TF'?'Benar atau Palsu':'Pilihan makna ayat'}</h1><p>${esc(i.prompt||(i.type==='ORDER'?'Tekan kalimah mengikut susunan ayat.':'Pilih ayat, kemudian pilih makna yang sepadan.'))}</p>${['MCQ','PAIR'].includes(i.type)?'<p class="notice">Pilih makna lengkap seluruh ayat, bukan hanya sebahagian maknanya.</p>':''}${i.type==='ORDER'?orderPanel(t,checked):i.type==='PAIR'?pairPanel(t,checked):`<section class="card"><p class="arabic" lang="ar" dir="rtl">${esc(refs[i.arabic_ref])}</p></section>${audioControls(c.verses.find(v=>v.id===i.ayat_ids[0]).audio_id)}${i.type==='TF'?`<section class="card"><span class="eyebrow">MAKNA UNTUK DISEMAK</span><p class="meaning">${esc(refs[i.displayed_meaning_ref])}</p><p class="muted">Tentukan sama ada makna di atas sepadan dengan ayat Arab ini.</p></section><div class="stack">${[true,false].map(value=>`<button class="btn answer ${s.draft===value?'selected':''}" data-action="truth" data-value="${value}" aria-pressed="${s.draft===value}" ${checked?'disabled':''}>${value?'Benar':'Palsu'}</button>`).join('')}</div>`:`<div class="stack">${s.orders[i.id].option_refs.map(ref=>`<button class="btn answer ${s.draft===ref?'selected':''}" data-action="choice" data-value="${esc(ref)}" aria-pressed="${s.draft===ref}" ${checked?'disabled':''}>${esc(refs[ref])}</button>`).join('')}</div>`}`}${checked?`<section class="card feedback" role="status"><h2>${receipt.units.every(u=>u.correct)?'Betul.':'Mari lihat semula.'}</h2><div class="feedback-content">${i.type==='ORDER'?'<span class="arabic" lang="ar" dir="rtl">'+i.answer_token_refs.map(id=>esc(refs[id])).join(' ')+'</span>'+audioControls(c.verses.find(v=>v.id===i.ayat_ids[0]).audio_id):i.type==='PAIR'?i.valid_pairs.map(([l,r])=>'<strong>Ayat '+esc(c.verses.find(v=>v.id+'-AR'===l).verse_key.split(':')[1])+'</strong> · '+esc(refs[r])).join('<br>'):esc(refs[i.correction_ref||i.answer_ref])}</div></section><button class="btn gold" data-action="nextQuestion">${s.cursor===s.itemIds.length-1?'Lihat keputusan':'Soalan seterusnya'}</button>`:`<button class="btn gold" data-action="check" ${s.draft===null||(i.type==='ORDER'&&s.draft.length!==i.token_refs.length)||(i.type==='PAIR'&&Object.keys(s.draft).length!==i.left_refs.length)?'disabled':''}>Semak jawapan</button>`}${button('Rehat dahulu · simpan latihan','journey','outline')}`}
function render(){clearTimers();if(route==='flash')learning.openFlash(flashId);if(['learn','words'].includes(route)){learning.setStudyView(route);learning.openStudyUnit(activeUnit,activeToken);}document.title=`${r.title} · ${r.buildId}`;if(route==='opening'){opening();return}root.className=`shell ${profile==='kid'?'kid':''} ${textSize==='large'?'text-large':''}`;root.innerHTML=header()+`<div class="body">${storageNotice()}${stageNavigation()}${route==='intro'?intro():route==='learn'?learn():route==='words'?words():route==='readingEnd'?readingEnd():route==='practice'?practice():route==='flash'?flash():route==='fullReading'?fullReading():route==='sources'?sources():route==='records'?recordsPage():route==='sequenceMenu'?sequenceMenu():route==='sequence'?extensionView('sequence'):route==='reverse'?extensionView('reverse'):route==='reflect'?reflectionView():route==='stage'?stageView():journey()}${stageReturn()}</div>`+footer()+zoomPanel();mountZoom();if(route==='learn')learning.markUnitDisplayed(activeUnit);if(route==='words')learning.markTokenDisplayed(c.tokens.filter(t=>t.ayat_id===activeUnit)[activeToken].id);for(const detail of root.querySelectorAll('details[data-unit]'))detail.addEventListener('toggle',()=>{if(!detail.open||route!=='journey')return;records[profile].selectedUnit=detail.dataset.unit;save();if(!storageOK&&!root.querySelector('[data-save-warning]')){const p=document.createElement('p');p.className='notice';p.dataset.saveWarning='true';p.setAttribute('role','status');p.textContent='Pilihan tidak dapat disimpan. Anda masih boleh meneruskan pratonton.';root.querySelector('.body').prepend(p)}});}
root.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const action=b.dataset.action;if(b.disabled)return;
if(['guidedNext','sequenceStart','extraStart','extraResume','extraPick','extraUndo','extraClear','extraCheck','extraNext','reflectToggle'].includes(action)){try{learning.stopAudio('journey-action');if(action==='guidedNext'){runGuidedNext();return}if(action==='reflectToggle'){const id=b.dataset.value;journeyTools.reflect(id,!journeyTools.state().reflection[id]);render();return}if(action==='sequenceStart'){const [level,start]=b.dataset.value.split(':').map(Number);learning.pauseTraining();journeyTools.start('sequence',{level,start});go('sequence');return}if(action==='extraStart'||action==='extraResume'){const kind=b.dataset.value;learning.pauseTraining();if(action==='extraStart')journeyTools.start(kind);else journeyTools.resume(kind);go(kind);return}const kind=route;if(!['sequence','reverse'].includes(kind))return;if(action==='extraPick')journeyTools.edit(kind,kind==='sequence'?'pick':'choose',b.dataset.value);if(action==='extraUndo')journeyTools.edit(kind,'undo');if(action==='extraClear')journeyTools.edit(kind,'clear');if(action==='extraCheck')journeyTools.check(kind);if(action==='extraNext')journeyTools.next(kind);render()}catch{notice='Tindakan belum berjaya. Semak pilihan atau kembali ke perjalanan.';render()}return}

if(action==='textSize'){textSize=textSize==='large'?'normal':'large';write(prefix+'textSize',textSize);render();return}
if(action==='zoomImage'){if(!assets[b.dataset.value])return;learning.stopAudio('image-zoom');zoomTarget=b.dataset.value;zoomScale=100;zoomReturnScroll=window.scrollY||0;render();return}
if(['zoomIn','zoomOut','zoomFit'].includes(action)){if(!zoomTarget)return;zoomScale=action==='zoomFit'?100:Math.max(100,Math.min(250,zoomScale+(action==='zoomIn'?25:-25)));render();return}if(action==='zoomClose'){closeZoom();return}
if(action==='resetAsk'){if(route!=='records')return;resetPending=profile;render();return}if(action==='resetCancel'){resetPending=null;render();return}
if(action==='resetConfirm'){if(route!=='records'||resetPending!==profile||b.dataset.value!==profile)return;try{journeyTools.assertReset();learning.resetCurrentProfile({confirmed:true});journeyTools.reset({confirmed:true});records[profile].selectedUnit=null;save();pairLeft=null;notice='Rekod profil ini telah dikosongkan. Semak notis jika storan tidak dapat menyimpan perubahan.';}catch{notice='Rekod lama dilindungi atau perubahan belum dapat disimpan. Rekod asal tidak ditulis ganti.'}resetPending=null;render();return}
if(action==='exportRecord'){try{downloadRecord()}catch{notice='Muat turun tidak tersedia. Gunakan Lihat / salin rekod JSON.';render()}return}if(action==='flashReveal'){learning.stopAudio('flash-reveal');learning.revealFlash(!learning.currentFlash().revealed);render();return}
if(['audio','stopAudio','startTraining','resumeTraining','startFull','resumeFull','startRetention','resumeRetention','startRetry','resumeRetry','refreshEligibility','choice','truth','pairLeft','pairRight','unpair','orderPick','orderUndo','orderClear','check','nextQuestion'].includes(action)){try{if(action==='audio'){learning.playAudio(b.dataset.value);updateAudioUI();return}if(action==='stopAudio'){learning.stopAudio('user');updateAudioUI();return}learning.stopAudio('training-action');if(action==='startRetry'||action==='resumeRetry'){const scope=b.dataset.value;if(action==='startRetry')learning.startRetry(scope);else learning.resumeRetry(scope);retryScope=scope;trainingType='RETRY';pairLeft=null;notice='';}if(action==='refreshEligibility'){notice='';render();return}if(action==='startRetention'||action==='resumeRetention'){if(action==='startRetention')learning.startRetention();else learning.resumeRetention();notice='';pairLeft=null;trainingType='RETENTION';}if(action==='startFull'||action==='resumeFull'){pairLeft=null;trainingType='FULL';if(action==='startFull')learning.startFull();else learning.resumeFull();}if(action==='orderPick')learning.orderPick(b.dataset.value);if(action==='orderUndo')learning.orderUndo();if(action==='orderClear')learning.orderClear();if(action==='pairLeft'){pairLeft=b.dataset.value;render();return}if(action==='pairRight'){if(!pairLeft)return;learning.pair(pairLeft,b.dataset.value);pairLeft=null;}if(action==='unpair')learning.unpair(b.dataset.value);if(action==='startTraining'||action==='resumeTraining'){pairLeft=null;trainingType=['TF','PAIR','ORDER','FULL','RETENTION'].includes(b.dataset.value)?b.dataset.value:'MCQ';if(action==='startTraining')learning.startTraining(trainingType);else learning.resumeTraining(trainingType);}if(action==='choice')learning.choose(b.dataset.value);if(action==='truth')learning.choose(b.dataset.value==='true');if(action==='check')learning.check();if(action==='nextQuestion'){learning.nextQuestion();pairLeft=null;}go('practice/'+trainingType+(trainingType==='RETRY'?'/'+retryScope:''));}catch(error){notice=({NO_RETRY_TARGETS:'Tiada jawapan terkini salah dalam skop ini. Kembali ke perjalanan.',NOT_DUE:'Belum cukup 24 jam. Semak masa kelayakan pada perjalanan.',FULL_REQUIRED:'Lengkapkan ujian gabungan dahulu.',CLOCK_ROLLBACK:'Masa peranti lebih awal daripada rekod. Semak tetapan masa.',CLOCK_INVALID:'Masa peranti tidak sah.'})[error.message]||'Tindakan belum berjaya. Kembali ke perjalanan dan cuba semula.';render()}return}
if(b.dataset.action==='go'){go(b.dataset.value);return}if(b.dataset.action==='study'){const id=b.dataset.value;if(!c.verses.some(v=>v.id===id))return;const previous=learning.getCurrentStudy();activeUnit=id;activeToken=previous?.ayatId===id?previous.tokenIndex:0;go('learn/'+id+'/'+activeToken);return}if(b.dataset.action==='profile'&&profiles.includes(b.dataset.value)&&b.dataset.value!==profile){clearTimers();save();profile=b.dataset.value;resetPending=null;zoomTarget=null;learning.selectProfile(profile);journeyTools.selectProfile(profile);save();if(['learn','words'].includes(route)){const last=learning.getCurrentStudy();go((last?last.view+'/':'learn/')+(last?.ayatId||c.verses[0].id)+'/'+(last?.tokenIndex||0));}else if(route==='flash')go('flash/'+(learning.currentFlash()?.item.id||learning.flashCards()[0].id));else if(route==='practice')go('journey');else render();}});
window.addEventListener('hashchange',()=>{resetPending=null;zoomTarget=null;learning.stopAudio('navigation');const nextRoute=routeFromHash();if(['sequence','reverse'].includes(route)&&nextRoute!==route)journeyTools.pause(route);if(nextRoute==='practice')journeyTools.pause();if(route==='practice'&&nextRoute!=='practice')learning.pauseTraining();route=nextRoute;render();window.scrollTo(0,0);root.querySelector('h1')?.setAttribute('tabindex','-1');root.querySelector('h1')?.focus({preventScroll:true});});
document.addEventListener('visibilitychange',()=>{if(route!=='opening')return;if(document.hidden)clearTimers();else{const im=document.getElementById('opening-image');if(im?.complete&&im.naturalWidth)startTimer(generation)}});
window.addEventListener('pagehide',()=>{journeyTools.pause();learning.pauseTraining();clearTimers()});
route=routeFromHash();render();
})();

